new='''  const mdTable = eventsData.tables.midas;
  const mdCol = mdTable ? mdTable.columns : [];
  const mdIdCol = mdCol.indexOf('id');
  const mdModeCol = mdCol.indexOf('mode');
  const midasRows = mdTable ? mdTable.rows : [];

  // правило 12: золото Midas; n — Δзолота (r · s · amount), при 0 событий нет
  function midasEvents(amount) {
    const out = [];
    if (amount === 0) return out;
    for (const row of midasRows) {
      out.push({ id: row[mdIdCol], mode: row[mdModeCol], n: amount });
    }
    return out;
  }

  const trTable = eventsData.tables.transmuter;
  const trCol = trTable ? trTable.columns : [];
  const trIdCol = trCol.indexOf('id');
  const trBarCol = trCol.indexOf('bar');
  const trModeCol = trCol.indexOf('mode');
  const transmuterRows = trTable ? trTable.rows : [];

  // правило 13: бары Transmuter; n — Δbar, строки только с этим баром
  function transmuterEvents(bar, amount) {
    const out = [];
    if (amount === 0) return out;
    for (const row of transmuterRows) {
      if (row[trBarCol] !== bar) continue;
      out.push({ id: row[trIdCol], mode: row[trModeCol], n: amount });
    }
    return out;
  }

  const chTable = eventsData.tables.cherry;
  const chCol = chTable ? chTable.columns : [];
  const chIdCol = chCol.indexOf('id');
  const chSlotCol = chCol.indexOf('slot');
  const chModeCol = chCol.indexOf('mode');
  const chNCol = chCol.indexOf('n');
  const cherryRows = chTable ? chTable.rows : [];

  // правило 14: выстрел с вишнями; st = { charges, cherry } меняется на месте
  function cherryFire(st, slot) {
    if (slot === c['cherry.slot']) {
      if (st.charges[slot] < c['fire.minCharge']) return { fired: false, usedCherry: false };
      st.charges[slot] = st.charges[slot] - 1;
      st.cherry = st.cherry + 1;
      return { fired: true, usedCherry: false };
    }
    if (st.cherry > 0) {
      st.cherry = st.cherry - 1;
      return { fired: true, usedCherry: true };
    }
    if (st.charges[slot] < c['fire.minCharge']) return { fired: false, usedCherry: false };
    st.charges[slot] = st.charges[slot] - 1;
    return { fired: true, usedCherry: false };
  }

  function cherryEvents(slot, usedCherry) {
    const out = [];
    if (!usedCherry) return out;
    for (const row of cherryRows) {
      if (row[chSlotCol] !== slot) continue;
      out.push({ id: row[chIdCol], mode: row[chModeCol], n: row[chNCol] });
    }
    return out;
  }

'''
